package main

// The museum. The captain asked for a guided walk through the laboratory where
// every piece is explained the way you would explain it leaning on a counter -
// no jargon, no assumed background, and every symbol translated into words the
// moment it appears.
//
// Two things live here: the DICCIONARIO, which decodes every symbol the visitor
// will meet, and the SALAS, eight rooms curated as a story rather than as a
// chronology. The last room is the honest one: the laboratory's own mistakes,
// with names and dates. That room is the point.

import (
	"encoding/json"
	"net/http"
	"path/filepath"
	"strings"
)

// Palabra is one entry of the glossary at the museum door.
type Palabra struct {
	Simbolo string `json:"simbolo"`
	Nombre  string `json:"nombre"`
	Criollo string `json:"criollo"`
}

// Pieza is one stop of the tour.
type Pieza struct {
	N        int        `json:"n"`
	Titulo   string     `json:"titulo"`
	Gancho   string     `json:"gancho"`
	Criollo  string     `json:"criollo"`
	Metafora string     `json:"metafora"`
	Mirar    string     `json:"mirar"`
	Simbolos [][]string `json:"simbolos"`
	Honesto  string     `json:"honesto"`
	Lamina   string     `json:"lamina"` // plate file name, or ""
	Exp      string     `json:"exp"`    // experiment dir to run live, or ""
	Hallazgo string     `json:"hallazgo"`
	Enlace   string     `json:"enlace"` // dedicated gallery page, or ""
	Emoji    string     `json:"emoji"`
	Vel      string     `json:"vel"`
}

// SalaMuseo groups the stops of one room.
type SalaMuseo struct {
	Clave  string  `json:"clave"`
	Numero string  `json:"numero"`
	Titulo string  `json:"titulo"`
	Intro  string  `json:"intro"`
	Piezas []Pieza `json:"piezas"`
}

// diccionario decodes every symbol a visitor can bump into. Written for someone
// who has never seen a Greek letter in their life and should not feel small
// about it.
var diccionario = []Palabra{
	{"s", "el punto de la pregunta", "Es el lugar donde le preguntás algo a la máquina. Como el dial de una radio: lo movés y la máquina contesta otra cosa. Tiene dos perillas a la vez, por eso abajo aparecen σ y t."},
	{"σ", "sigma — la perilla horizontal", "De qué lado de la línea estás parado. Es la mitad «izquierda-derecha» del punto s. Toda la Hipótesis es una apuesta sobre esta perilla: dice que en los ceros vale siempre ½."},
	{"t", "la altura", "La mitad «arriba-abajo» del punto s. Es la altura a la que estás mirando, como los metros marcados en un poste."},
	{"ρ", "rho — una perla", "Un cero: un punto donde la máquina se calla del todo. En este taller los llamamos perlas, porque hay que pescarlas de a una."},
	{"γ", "gamma — la altura de una perla", "A qué altura quedó pescada esa perla. La primera está en γ = 14.134725. Es su número de identidad."},
	{"ζ", "zeta — la máquina", "La máquina que suma 1 + 1/2ˢ + 1/3ˢ + 1/4ˢ + … para el punto que le des. Euler descubrió que esa suma sobre TODOS los números es igual a una multiplicación sobre SOLO los primos. O sea: la máquina escucha a los primos."},
	{"ξ", "xi — la máquina peinada", "La misma máquina, pero vestida con unos factores extra que la vuelven perfectamente simétrica respecto de la línea del medio. Es la versión que se mira al espejo sin despeinarse."},
	{"Z(t)", "el detector de metales", "Un truco: sobre la línea del medio esta función da números normales (no de los raros), así que se puede ver dónde cambia de signo. Donde cambia de signo hay una perla enterrada. Es literalmente pasar el detector por la playa."},
	{"θ", "theta — el reloj", "El giro exacto que hay que aplicarle a la máquina para que el detector Z dé números normales. Es la perilla de sintonía."},
	{"λₙ", "lambda — los dientes del molde", "Una lista infinita de números — λ₁, λ₂, λ₃… — sacados de la máquina. Un teorema de Li dice: la Hipótesis es cierta si y solo si NINGUNO de estos números es negativo. λ₁ vale 0.0230957."},
	{"n", "el número de diente", "Cuál de los dientes de la lista estás mirando. El primero, el segundo, el cuarenta."},
	{"w", "el cambiaformas", "Una transformación que agarra el plano entero y lo mete adentro de un círculo. Lo de afuera pasa a ser lo de adentro. Se calcula w = 1 − 1/ρ."},
	{"p", "un primo cualquiera", "La letra que se usa para decir «acá va un número primo». Como decir «Fulano»."},
	{"ψ(x)", "psi — la escalera de los primos", "Una escalera que sube un escalón cada vez que aparece un primo (o una potencia de primo). El escalón no es de 1: es de ln p, el tamaño del primo medido en logaritmos."},
	{"π(x)", "pi de x — cuántos primos hay", "Cuántos primos hay hasta el número x. Ojo: NO es el π de 3.14159, es otra cosa que se escribe igual. Los matemáticos son así."},
	{"Σ", "sigma mayúscula — «sumá todo esto»", "Un cartelito que dice «sumá todos los términos que siguen». Nada más que eso."},
	{"Π", "pi mayúscula — «multiplicá todo esto»", "Lo mismo que Σ pero multiplicando en vez de sumar."},
	{"ln", "el logaritmo natural", "Le preguntás a un número «¿a qué potencia hay que elevar 2.718 para llegar a vos?». Sirve para aplastar números gigantes a un tamaño manejable: ln de un millón es apenas 13.8."},
	{"e", "el número 2.71828…", "Una constante que aparece sola en todo lo que crece o decrece de manera natural: intereses, poblaciones, enfriamiento del mate."},
	{"i", "la unidad imaginaria", "Un número inventado que cumple i × i = −1. Suena a trampa y no lo es: sirve para que los puntos vivan en un plano en vez de en una recta. Es lo que le da la segunda perilla a s."},
	{"|x|", "el tamaño, la distancia", "Las dos barritas quieren decir «el tamaño de esto, sin importar el signo». Una distancia nunca puede ser negativa — eso lo dijo el capitán y resultó ser la clave de una fórmula entera."},
	{"Re / Im", "parte real / parte imaginaria", "Las dos mitades de un punto del plano: Re es cuánto se corrió a los costados, Im cuánto subió o bajó."},
	{"Γ", "gamma mayúscula — el factorial estirado", "El factorial (5! = 5×4×3×2×1) pero estirado para que funcione con cualquier número, no solo con los enteros. Es una de las piezas del vestido de ξ."},
	{"Λ(n)", "lambda mayúscula — el peso de un número", "Vale ln p si el número es una potencia de un primo p, y vale cero si no. Es la manera de decir «este número aporta a la escalera, este otro no»."},
	{"O(x)", "«no crece más rápido que»", "Una manera de acotar. Decir que un error es O(√x) es decir «como mucho crece como la raíz cuadrada», sin comprometerse con el número exacto."},
	{"⟺", "«si y solo si»", "Las dos cosas van juntas o no va ninguna. Si pasa una pasa la otra, y al revés también."},
	{"1e-16", "un decimal seguido de quince ceros", "La manera corta de escribir números diminutos. 1e-16 es 0.0000000000000001 — el límite de precisión de una computadora común. Cuando una medición da eso, es exacta hasta donde la máquina puede ver."},
	{"τ = t/2π", "tau — la altura contada en vueltas", "Pensá en el reloj de la máquina dando vueltas: τ es cuántas vueltas enteras entran en la altura t. A la altura 10000 entran 1591,549. Y ojo con esto: τ sale de una altura, pero se usa como número de PASO — es un mojón en la cuenta de los pasos que vas sumando. Antes del paso número τ la espiral se porta de una manera (y ahí la curva madre no vale), después del paso τ se porta de otra, y todas las leyes de vueltas se cuentan desde ese mojón. Dos coincidencias feas: el τ(n) de Ramanujan de la sala del segundo piso, y el τ del escudo del batido, se escriben igual y no tienen nada que ver con éste."},
	{"la cuerda", "el atajo entre dos direcciones", "Pensá en las dos agujas de un reloj separadas por un angulito. La cuerda es el atajo: la distancia en línea recta entre las dos puntas, no el arco que las une por afuera. Cuanto más chiquito el ángulo, más corta la cuerda. Y acá eso pesa al revés de lo que parece: la curva madre es un paso dividido por la cuerda, así que con la cuerda cortita estás dividiendo por un número chiquito y el resultado es GRANDE — la espiral pasa lejos del ojo, dando vueltas anchas. No confundir con la cuerda de la guitarra que aparece en otras piezas: acá es la del círculo."},
	{"la espiral", "el camino que va dejando la cuenta", "La máquina suma un montón de pedacitos. Sumalos de a uno y, después de cada suma, marcá en el piso dónde quedaste parado: eso es la espiral. Los pasos no van derecho — cada uno sale un poco torcido respecto del anterior — así que el camino se enrosca y va cerrando vueltas cada vez más apretadas. Es, literalmente, el dibujo de la cuenta haciéndose. Nació de una pregunta del capitán: «¿has visto un coseno en espiral, convergiendo en un punto?» — o sea: una espiral que se va cerrando hasta quedarse quieta en un punto."},
	{"el ojo", "el punto al que se enrosca la espiral", "El agujerito del medio del remolino: el lugar donde la espiral termina de enroscarse y se queda quieta. Ese punto ES el valor de la máquina a esa altura, y se calcula con lo que ya sumaste más la receta de Euler–Maclaurin para el pedazo que falta. Lo que lo vuelve instrumento y no dibujo: la espiral gira y el ojo se queda quieto — midiendo con 150, 300, 450 y 600 pasos se movió 0,006 / 0,004 / 0,002 / 0,003. Y si estás parado en la línea del medio, las alturas donde el ojo cae justo en el origen son las perlas. Cuidado con el nombre: en las salas de las tormentas «el ojo» quiere decir otra cosa, el centro del temporal; acá es el centro del remolino."},
	{"Euler–Maclaurin", "la receta para completar la suma", "Sumaste los primeros mil pedacitos de algo infinito y te falta la cola. Esta receta, de hace casi trescientos años, te dice cuánto vale esa cola con unas pocas correcciones, en vez de sumar para siempre. Acá se usa para saber en qué punto exacto se va a quedar quieta la espiral sin tener que dar infinitas vueltas — es lo que hace que el ojo se pueda calcular. No es del taller: es matemática de libro."},
	{"la curva madre", "la ecuación que da la forma de la espiral", "Imaginate que en cada paso alguien te mide con una cinta la distancia hasta el ojo del remolino, y la anota. La curva madre es la cuenta que te da ese número de antemano, sin medir: el largo del paso dividido por la cuerda. Escrita en símbolos, R = n^(−σ)/(2·|sin(t/2n)|). De esa sola cuenta salen las cuatro cosas que se ven en la espiral: a qué ritmo se va achicando, cada cuántos pasos da una vuelta entera, dónde tiene su cintura más flaca (el paso en que pasa más cerca del ojo) y cuánto se cierra en cada vuelta. Le decimos madre porque las otras cuatro son hijas de ésta. Y lo honesto: es exacta dentro del modelo declarado, no necesariamente para la espiral verdadera."},
	{"el alias (efecto estroboscópico)", "la rueda que parece girar al revés", "Es el ventilador bajo las luces de una discoteca, o la rueda del carro en las películas viejas: gira para adelante y vos la ves girando para atrás, o quieta. Pasa porque no la mirás todo el tiempo, la mirás a saltos. Acá igual: la espiral se mide solo en números enteros, y cerca de τ cada paso da casi una vuelta entera, así que el giro que uno VE no es el giro que hay. A esa franja engañosa le decimos acá zona alias."},
	{"el tambor", "el instrumento que contesta quién golpea", "Si la altura de la máquina fuera un sonido, ¿quién lo está tocando? El tambor es el experimento que escucha eso y separa las voces. La respuesta medida: golpean los primos y sus potencias, y nadie más. El 2 sonó 0,3524 contra el 0,3536 que manda la aritmética; el 6 y el 15 quedaron mudos, en 0,003. La señal da 39,6 veces el silencio."},
	{"el parche", "el cuero del tambor: dónde se para cada número", "El cuero donde se golpea. Acá está dibujado de manera que cada número n queda a distancia ln n del centro — ln es el logaritmo, el aplastador de números grandes que está unas entradas más arriba en este mismo diccionario. Golpe cerca del centro, BOOM grave; golpe cerca del aro, TAK agudo — con la misma energía lo único que cambia es el timbre. Así le decimos acá a esa forma de acomodar los números para poder escucharlos."},
	{"la frustración", "cuando los vecinos no se pueden poner de acuerdo", "Tres amigos en una mesa: dos se llevan bien y el tercero se pelea con los dos. No hay manera de sentarlos contentos a todos. Eso es un triángulo frustrado. El número cuenta qué proporción de los triángulos de la red está así: da 0 si todos los enlaces tiran para el mismo lado, y alrededor de 0,537 si los signos se ponen al azar. En la fase IX pareció que era esto lo que movía el resultado, pero la fase X lo desmintió en casa: tres familias con la MISMA frustración dieron participaciones que se diferencian por un factor seis. Lo que decide no es cuánta frustración hay, sino DÓNDE vive el signo — si está puesto en los sitios o en los enlaces."},
	{"PR/N", "la participación — cuánto se reparte la vibración", "Golpeás una mesa: si tiembla toda, la participación es alta; si tiembla nada más que una esquinita, es baja. Este número vale casi 1 cuando la vibración se reparte por toda la mesa y se va a cero cuando queda atrapada en un rincón. Se mira siempre pegado al resultado, porque un número lindo conseguido atrapando la vibración no vale: en el taller se pide 0,090 o más para llamarlo comparable, y por debajo de 0,070 se lo llama atrapado."},
	{"‖P‖_F", "la pared de fuerza — cuánto habría que empujar", "Tenés una guitarra desafinada y querés que cada cuerda dé justo la nota que le corresponde: hay que apretar las clavijas, y se puede medir cuánta fuerza total hace falta para lograrlo. Esto es lo mismo, pero con nuestro instrumento: cuánto habría que empujarlo para que sus notas caigan justo sobre las perlas de verdad. La cuenta dio que hace falta AL MENOS 7496, y todo el presupuesto de empuje de las fases era 30: doscientas cincuenta veces más. Ni siquiera el detalle fino entra — ese solo pide 91,4, el triple del presupuesto. No era falta de ingenio: la caja en la que estábamos trabajando no da. Así le decimos acá a ese tope."},
}

func (p *puente) apiMuseo(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	_ = json.NewEncoder(w).Encode(map[string]any{
		"diccionario": diccionario,
		"guiado":      recorridoGuiado,
		"completo":    salasCompletas,
	})
}

// apiLaminaMuseo serves a plate by file name rather than by experiment, since a
// museum stop may hang a plate produced by a different experiment than the one
// it invites you to run.
func (p *puente) apiLaminaMuseo(w http.ResponseWriter, r *http.Request) {
	f := r.URL.Query().Get("f")
	if f == "" || strings.ContainsAny(f, `/\`) || strings.Contains(f, "..") {
		http.NotFound(w, r)
		return
	}
	p.mu.Lock()
	ruta := p.rutaLamina(f)
	p.mu.Unlock()
	if ruta == "" {
		http.NotFound(w, r)
		return
	}
	switch strings.ToLower(filepath.Ext(ruta)) {
	case ".svg":
		w.Header().Set("Content-Type", "image/svg+xml; charset=utf-8")
	case ".png":
		w.Header().Set("Content-Type", "image/png")
	default:
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	}
	http.ServeFile(w, r, ruta)
}

